/**
 * The shape of a unit guidebook: the written page a student opens from the
 * GUIDEBOOK key on the unit card, before or between lessons.
 *
 * Two halves, kept in two files on purpose:
 *   - the WORDS (key ideas, common mistakes), hand written in uNGuide.ts, where
 *     every chemistry line names the pool entry it quotes;
 *   - the DRAWINGS (one mini example per lesson), generated by a script with
 *     RDKit into uNGuide.figures.ts, so no structure is typed from memory.
 *
 * Pure data, no React, so the node test suite can walk all of it.
 */
import type { Figure } from "../onboarding/figures";
import type { ChargeGateNode } from "../charge/chargeGateModel";

/** One thing drawn in a mini example, left to right. */
export type GuidePanel =
  /** A structure. `smiles` is what RDKit parsed; `figure` is its drawing. */
  | { readonly kind: "mol"; readonly smiles: string; readonly name?: string; readonly figure: Figure }
  /** A reaction arrow with its conditions above and below. */
  | { readonly kind: "arrow"; readonly over: string; readonly under?: string }
  | { readonly kind: "plus" }
  /** The double headed resonance arrow between two contributors. */
  | { readonly kind: "resonance" }
  /** "About the same as", for a comparison. */
  | { readonly kind: "about" }
  /** "Is more stable than", for a comparison. */
  | { readonly kind: "beats" }
  /** Starts a second row, for a two condition example. */
  | { readonly kind: "break" }
  /** A generic two product energy diagram. Draws no chemistry. */
  | { readonly kind: "energy" }
  /** A Huckel pi MO ladder computed by the script. */
  | {
      readonly kind: "ladder";
      readonly levels: readonly { readonly name: string; readonly x: number; readonly nodes: number; readonly electrons: number }[];
      readonly homo: number;
      readonly lumo: number;
    };

export interface GuideExample {
  /** One line under the drawing, saying what it shows. */
  readonly caption: string;
  readonly panels: readonly GuidePanel[];
  readonly placeholder: true;
}

/**
 * A chemistry line in the guide, tied to the pool entry it came from. The
 * guide test fails any `quote` that is not word for word in that entry's
 * explanation or correct option, so the guide can never say something the
 * questions do not.
 */
export interface Sourced {
  readonly source: string;
  readonly quote: string;
}

export interface GuideIdea extends Sourced {
  /** Plain language, one sentence or two. */
  readonly text: string;
}

export interface GuideMistake extends Sourced {
  /** What students do. */
  readonly mistake: string;
  /** The one line that fixes it. */
  readonly fix: string;
}

export interface GuideLesson {
  /** The pathway node id. The START key plays this lesson. */
  readonly node: string;
  readonly ideas: readonly GuideIdea[];
  /** Where the example's caption comes from. */
  readonly example: Sourced;
}

export interface GuideStage {
  readonly id: string;
  /** "Stage A", drawn as the eyebrow. */
  readonly label: string;
  readonly title: string;
  /** Side quest stages say so, because nothing on the main line waits for them. */
  readonly optional: boolean;
  readonly lessons: readonly GuideLesson[];
  /** The stage's checkpoint quiz node, or null. */
  readonly checkpoint: string | null;
  readonly mistakes: readonly GuideMistake[];
}

export interface UnitGuide {
  readonly unitId: string;
  readonly intro: string;
  readonly stages: readonly GuideStage[];
  readonly examples: Readonly<Record<string, GuideExample>>;
  readonly placeholder: true;
}

/**
 * How the guide may enter a lesson, worked out by the pathway (it owns the
 * unlock rules and the charge). The guide only reads this.
 */
export interface LessonDoor {
  readonly title: string;
  readonly state: "done" | "current" | "open" | "review" | "locked";
  /** Null when the lesson cannot be entered (locked, or nothing written). */
  readonly gate: ChargeGateNode | null;
  /** Why it is shut, in the chip's own words, or null when it is open. */
  readonly note: string | null;
}
